class Node {
    int data;
    Node next;
    Node prev;

    Node(int data) {
        this.data = data;
        this.next = null;
        this.prev = null;
    }
}

class DoublyLinkedList {
    Node head;

    // Clone method
    public DoublyLinkedList clone() {
        if (head == null) {
            return null;
        }

        DoublyLinkedList cloneList = new DoublyLinkedList();
        Node current = head;
        Node cloneCurrent = null;

        while (current != null) {
            Node newNode = new Node(current.data);
            if (cloneList.head == null) {
                cloneList.head = newNode;
                cloneCurrent = newNode;
            } else {
                cloneCurrent.next = newNode;
                newNode.prev = cloneCurrent;
                cloneCurrent = newNode;
            }
            current = current.next;
        }

        return cloneList;
    }

    // Reverse method
    public void reverse() {
        if (head == null) {
            return;
        }

        Node current = head;
        Node temp = null;

        // Swap next and prev for all nodes
        while (current != null) {
            temp = current.prev; 
            current.prev = current.next; 
            current.next = temp;         
            current = current.prev; // Move to the next node (which is previous due to swap)
        }

        // Resetting head to the new first node
        if (temp != null) {
            head = temp.prev; // The new head should be the last non-null node processed
        }
    }
}
