import requests

def patch_request(url, data):
    try:
        response = requests.patch(url, json=data)

        # Log response status code and data
        with open('log.txt', 'a') as logfile:
            logfile.write(f"Status Code: {response.status_code}\n")
            logfile.write(f"Response Data: {response.json()}\n")

        if response.status_code == 200:
            print("PATCH request was successful.")
        elif response.status_code == 404:
            print("Error 404: Not Found.")
        elif response.status_code == 500:
            print("Error 500: Internal Server Error.")
        else:
            print(f"Unexpected Error: {response.status_code}")

    except requests.exceptions.Timeout:
        print("Request timed out. Please try again later.")
    except requests.exceptions.ConnectionError:
        print("Network error occurred. Check your connection.")
    except Exception as e:
        print(f"An error occurred: {e}")

